// Monta a "comanda da semana" de cada restaurante.
// Todos os números vêm das views do Supabase; aqui só formatamos (nenhuma conta nova).
const resumo = $('Resumo semanal').all().map(i => i.json);
const alertas = $('Alerta de caixa').all().map(i => i.json);
const promos = $('Promoções').all().map(i => i.json);
const canc = $('Cancelamentos altos').all().map(i => i.json);
const nomes = {1: 'Brasa Burger', 2: 'Marmita da Lu', 3: 'Forno Pampulha'};
const brl = v => 'R$ ' + Number(v).toLocaleString('pt-BR', {minimumFractionDigits: 2, maximumFractionDigits: 2});
const dm = s => { const [y, m, d] = s.split('-'); return `${d}/${m}`; };
const addDias = (s, n) => { const d = new Date(s + 'T00:00:00Z'); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); };
const linha = (rotulo, valor) => rotulo.padEnd(20, ' ') + valor.padStart(12, ' ');
const out = [];
for (const id of [1, 2, 3]) {
  const semanas = resumo.filter(r => r.restaurante_id === id).sort((a, b) => b.semana.localeCompare(a.semana));
  const s = semanas[1] || semanas[0]; // última semana completa (a mais recente vai só até 31/10)
  const comanda = [
    '================================',
    `COMANDA DA SEMANA · ${dm(s.semana)}-${dm(addDias(s.semana, 6))}`,
    `${nomes[id]} · ${s.pedidos_entregues} pedidos`,
    '--------------------------------',
    linha('Faturamento bruto', brl(s.faturamento_bruto)),
    linha('(-) Descontos', brl(s.descontos)),
    linha('(-) Taxas', brl(s.taxas_plataforma)),
    linha('(-) Insumos', brl(s.custo_insumos)),
    '--------------------------------',
    linha('MARGEM REAL', brl(s.margem_contribuicao)),
    '================================',
  ].join('\n');
  const dias = {1: 'segunda', 2: 'terça', 3: 'quarta', 4: 'quinta', 5: 'sexta', 6: 'sábado', 7: 'domingo'};
  const cx = alertas.find(a => a.restaurante_id === id);
  const f = [];
  f.push(`Semana ${dm(s.semana)}-${dm(addDias(s.semana, 6))}: faturamento ${brl(s.faturamento_bruto)}, descontos ${brl(s.descontos)}, taxas ${brl(s.taxas_plataforma)}, insumos ${brl(s.custo_insumos)}, margem real ${brl(s.margem_contribuicao)}.`);
  if (cx && cx.primeiro_dia_negativo) {
    f.push(`Caixa projetado (próximos 30 dias): fica negativo a partir de ${dm(cx.primeiro_dia_negativo)}; menor saldo ${brl(cx.menor_saldo_projetado)} em ${dm(cx.dia_menor_saldo)}.`);
  } else {
    f.push('Caixa projetado (próximos 30 dias): não fica negativo.');
  }
  for (const p of promos.filter(p => p.restaurante_id === id)) {
    f.push(`Promoção "${p.promocao}" (período 03/08-31/10): ${p.unidades_vendidas} unidades, desconto total ${brl(p.desconto_total)}, margem das vendas com desconto ${brl(p.margem_contribuicao)}, margem por unidade ${brl(p.margem_por_unidade)}.`);
  }
  for (const c of canc.filter(c => c.restaurante_id === id)) {
    f.push(`Cancelamentos (período 03/08-31/10): ${dias[c.dia_semana]}, ${c.turno}: ${String(c.taxa_cancelamento_pct).replace('.', ',')}% (${c.cancelados} de ${c.pedidos} pedidos), insumos perdidos ${brl(c.insumos_perdidos)}.`);
  }
  const fatos = f.map(x => '- ' + x).join('\n');
  out.push({json: {restaurante_id: id, comanda, fatos}});
}
return out;

